package ioc; import java.util.ArrayList;import java.util.LinkedHashSet;import java.util.List;import java.util.Set; public final class IocSet{private final Set<Ioc> iocs=new LinkedHashSet<>();public void add(Ioc ioc){if(ioc!=null&&ioc.type()!=IocType.UNKNOWN)iocs.add(ioc);}public void addAll(java.util.Collection<Ioc> values){if(values!=null)for(Ioc i:values)add(i);}public List<Ioc> all(){return new ArrayList<>(iocs);}public int size(){return iocs.size();}public List<Ioc> byType(IocType type){List<Ioc> out=new ArrayList<>();for(Ioc i:iocs)if(i.type()==type)out.add(i);return out;}}
